export { SEARCH_TOOL_NAMES, sessionRanASearch } from "./evidence-provenance-table";

/**
 * The sanctioned no-search record (`/create-task` Step 1a, and
 * `require-duplicate-check-record`'s `NO_CANDIDATES_LINE`).
 *
 * It reports an OUTCOME rather than claiming an action, so it is not a
 * provenance claim and this guard must stay silent on it. Kept as its own
 * constant rather than folded into the negative branch of the claim regex,
 * because the two say different things: one is "no claim here", the other is
 * "the sanctioned way to record having found nothing".
 */
export const NO_CANDIDATES_LINE = "Duplicate check: no candidates found.";

/**
 * Verbs and tool names that make a duplicate-check record a claim about an
 * action the author performed.
 *
 * Past tense is the discriminator, and it is doing real work: "search
 * `tasks_search` before filing" is instruction, "searched `tasks_search`" is
 * provenance. Only the second asserts anything checkable about this session.
 */
const SEARCH_CLAIM_RE =
  /\b(?:searched|queried|cross-referenced|grepped|ran\s+(?:a\s+)?(?:`?tasks[_.]s(?:earch|imilar)`?|search))\b/i;

/**
 * Instruction phrasings that must NOT count as provenance, checked before the
 * claim pattern.
 *
 * PR #2886 R1 found the hole this closes: an earlier version also matched a
 * bare tool name followed by `for`/`over`/`across`, so "run `tasks_search` for
 * duplicates before filing" — an instruction — read as a claim to have searched.
 * That inverted the module's own stated discriminator. Imperative openings are
 * excluded explicitly rather than by hoping the past-tense pattern misses them,
 * because a spec quoting the requirement next to satisfying it is common.
 */
const INSTRUCTION_RE =
  /\b(?:run|search|check|use|invoke|call|do)\s+(?:a\s+)?`?tasks[_.]s(?:earch|imilar)`?|\bbefore\s+filing\b|\byou\s+(?:must|should)\b/i;

/**
 * Extract the duplicate-check record's own text.
 *
 * Bounded to the record rather than run over the whole spec: a spec's `## Scope`
 * or `## Context` routinely says "searched X" about the INVESTIGATION, which is
 * a different claim and not this guard's business. Reads from the
 * `Duplicate check:` label to the end of its paragraph — the shape every
 * accepted form takes.
 *
 * Returns null when no record is present at all; that case belongs to
 * `require-duplicate-check-record`, which denies it.
 */
export function extractDuplicateCheckRecord(spec: string | null | undefined): string | null {
  if (typeof spec !== "string" || spec.trim() === "") return null;
  const match = /^[ \t]*(?:[-*+][ \t]+)?(?:\*\*)?duplicate check(?:\*\*)?[ \t]*:/im.exec(spec);
  if (!match) return null;

  const rest = spec.slice(match.index);
  // A blank line ends the record. Specs write it as one paragraph, and reading
  // past that would pull in unrelated prose that mentions searching.
  const end = rest.search(/\n[ \t]*\n/);
  return end === -1 ? rest : rest.slice(0, end);
}

/** True when the record asserts the author performed a search. */
export function claimsASearch(record: string | null): boolean {
  if (!record) return false;
  if (record.trim().startsWith(NO_CANDIDATES_LINE)) return false;
  // Instruction beats claim when both are present. The asymmetry is deliberate:
  // a missed claim is a false negative (safe direction), a misread instruction
  // is a false positive fired at an author who did nothing wrong.
  if (INSTRUCTION_RE.test(record)) return false;
  return SEARCH_CLAIM_RE.test(record);
}

/** The advisory text. Never a denial — this guard cannot block. */
export function buildProvenanceWarning(): string {
  return (
    `[duplicate-check-search-provenance] This spec's duplicate-check record says a search ` +
    `was run, and no \`tasks_search\` / \`tasks_similar\` / \`refs_status\` call appears in ` +
    `this session.\n\n` +
    `Run the search now, then correct the record to match what it returned — or replace it ` +
    `with the sanctioned form, "${NO_CANDIDATES_LINE}", which reports an outcome instead of ` +
    `claiming an action.\n\n` +
    `Why this matters more than the wording: the record's whole function is to be EVIDENCE ` +
    `that you looked. You are its only witness, so a reader has no way to check it — which ` +
    `is exactly how mt#4003 was filed against four tasks that already owned the work ` +
    `(mem#966).\n\n` +
    `If the search genuinely ran outside this session, say where in the record.\n` +
    `Override: ${OVERRIDE_ENV_VAR}=1`
  );
}

